/* Generated by awwwards-preview/export_theme.py from awwwards-preview/src (craft3d.js). Edit the source and re-run the export; changes made here are overwritten. */
/* Craft Traditions of Kutch: each craft shown on a real Shrujan piece (the
   user: no 3D form; on each scroll, the real cloth or dress). On a wide
   screen the section holds still while it is scrolled through, one screen
   per craft: the piece's photograph gives way to the next (a curtain rising
   from below), its close-up of the cloth with it, and the craft's name,
   words and the piece itself beside it; the list on the right shows where
   the reader is and takes a click. On a phone (or with reduced motion) the
   crafts simply follow one another down the page. (Kept as sj-craft3d.js, a
   module, so the theme loads it as before; it no longer needs three.js.) */
const root = document.querySelector('.cw');
if (root) {
  const shots = [...root.querySelectorAll('.cw__shot')];
  const texts = [...root.querySelectorAll('.cw__text')];
  const items = [...root.querySelectorAll('.cw__item')];
  const track = root.querySelector('.cw__track i');
  const n = shots.length;
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const pinned = () => !reduced && window.matchMedia('(min-width: 900px)').matches;
  let at = 0;

  const show = (i) => {
    if (i === at) return;
    const prev = at;
    at = i;
    shots.forEach((s, k) => {
      s.classList.toggle('is-on', k === i);
      s.classList.toggle('was-on', k === prev);
      s.classList.toggle('is-below', k > i);
    });
    texts.forEach((t, k) => t.classList.toggle('is-on', k === i));
    items.forEach((b, k) => { b.classList.toggle('is-on', k === i); b.setAttribute('aria-current', k === i ? 'true' : 'false'); });
    // the next piece's photographs are asked for before they are needed
    const next = shots[i + 1];
    if (next) next.querySelectorAll('img[loading="lazy"]').forEach((im) => { im.loading = 'eager'; });
  };

  let ticking = false;
  const read = () => {
    ticking = false;
    if (!pinned()) return;
    const r = root.getBoundingClientRect();
    const run = root.offsetHeight - window.innerHeight;
    const p = Math.min(1, Math.max(0, -r.top / Math.max(1, run)));
    if (track) track.style.transform = `scaleY(${p})`;
    show(Math.min(n - 1, Math.floor(p * n * 0.9999)));
  };
  const onScroll = () => { if (!ticking) { ticking = true; requestAnimationFrame(read); } };
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);

  // a click on a craft in the list scrolls to it
  items.forEach((b, k) => b.addEventListener('click', () => {
    if (!pinned()) { texts[k].scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
    const top = root.getBoundingClientRect().top + window.scrollY;
    const run = root.offsetHeight - window.innerHeight;
    const y = top + run * ((k + 0.5) / n);
    if (window.Shrujan && window.Shrujan.scrollToY) window.Shrujan.scrollToY(y);
    else window.scrollTo({ top: y, behavior: 'smooth' });
  }));

  // the first piece's photographs load as the section comes near; on a
  // phone each piece rises in as it reaches the screen
  if ('IntersectionObserver' in window) {
    new IntersectionObserver((es, io) => {
      if (es[0].isIntersecting) { io.disconnect(); shots[0].querySelectorAll('img').forEach((im) => { im.loading = 'eager'; }); root.classList.add('is-near'); }
    }, { rootMargin: '150% 0px' }).observe(root);
    const rise = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-seen'); rise.unobserve(e.target); } }), { threshold: 0.15 });
    [...shots, ...texts].forEach((el) => rise.observe(el));
  }
  root.classList.add('is-ready');
  read();
  // the page's loader, the hero and the 3D section's old listeners waited on this
  window.__sjCraftReady = true;
  document.dispatchEvent(new CustomEvent('sj:craft-ready'));
}
